80	void do_block(list_node_t *pcb_node, list_head *queue)
81	{
82	    list_del(pcb_node);
83	    list_add_tail(pcb_node, queue);
84	    list_entry(pcb_node, pcb_t, list)->status = TASK_BLOCKED;
85	}
