96	list_node_t* max_priority_node(void)
97	{
98	    uint64_t current_tick = get_ticks();
99	
100	    /*
101	     * The effective priority of a ready task is its static priority aged
102	     * by the number of timer intervals it has waited in the ready queue;
103	     * the lower the value, the higher the priority.
104	     */
105	    list_node_t *max_node = ready_queue.next;
106	    pcb_t *max_pcb = list_entry(max_node, pcb_t, list);
107	    int max_priority = (int)max_pcb->priority
108	        - (int)((current_tick - max_pcb->ready_tick) / timer_interval);
109	
110	    list_node_t *node;
111	    for (node = ready_queue.next->next; node != &ready_queue; node = node->next) {
112	        pcb_t *pcb = list_entry(node, pcb_t, list);
113	        int priority = (int)pcb->priority
114	            - (int)((current_tick - pcb->ready_tick) / timer_interval);
115	        if (priority < max_priority) {
116	            max_node = node;
117	            max_priority = priority;
118	        }
119	    }
120	
121	    return max_node;
122	}
