24	/* check all timers. if timeouts, call callback_func and free the timer */
25	void timer_check()
26	{
27	    disable_preempt();
28	
29	    uint64_t current_tick = get_ticks();
30	    list_node_t *node = timer_queue.next;
31	    while (node != &timer_queue) {
32	        timer_t *timer = list_entry(node, timer_t, list);
33	        if (current_tick >= timer->timeout_tick) {
34	            /* timeout: invoke the callback and remove the timer */
35	            timer->callback_func(timer->parameter);
36	            node = node->next;
37	            list_del(node->prev);
38	        } else {
39	            node = node->next;
40	        }
41	    }
42	
43	    enable_preempt();
44	}
