30	void binsem_op(int binsem_id, int op)
31	{
32	    disable_preempt();
33	
34	    binsem_node_t *node = &binsem_nodes[binsem_id];
35	    if (op == BINSEM_OP_LOCK) {
36	        node->sem--;
37	        if (node->sem < 0) {
38	            /* the semaphore is taken: block the current task */
39	            do_block(&current_running->list, &node->block_queue);
40	            scheduler();
41	        }
42	    } else if (op == BINSEM_OP_UNLOCK) {
43	        node->sem++;
44	        if (node->sem <= 0) {
45	            /* there are waiters: wake one of them up */
46	            do_unblock(node->block_queue.next);
47	            scheduler();
48	        }
49	    }
50	
51	    enable_preempt();
52	}

