26	static futex_node_t* get_node(volatile uint64_t *val_addr, int create)
27	{
28	    int bucket = futex_hash((uint64_t)val_addr);
29	    list_head *head = &futex_buckets[bucket];
30	
31	    /* search the bucket for a node matching this address */
32	    list_node_t *p;
33	    for (p = head->next; p != head; p = p->next) {
34	        futex_node_t *node = list_entry(p, futex_node_t, list);
35	        if (node->futex_key == (futex_key_t)val_addr) {
36	            return node;
37	        }
38	    }
39	
40	    if (create) {
41	        /* allocate and initialize a new node for this address */
42	        futex_node_t *node = (futex_node_t *)kmalloc(sizeof(futex_node_t));
43	        node->futex_key = (futex_key_t)val_addr;
44	        init_list_head(&node->block_queue);
45	        list_add_tail(&node->list, &futex_buckets[bucket]);
46	        return node;
47	    }
48	
49	    return NULL;
50	}
