52	void futex_wait(volatile uint64_t *val_addr, uint64_t val)
53	{
54	    disable_preempt();
55	
56	    futex_node_t *node = get_node(val_addr, 1);
57	    assert(node);
58	    if (*val_addr == val) {
59	        /* the value still matches: block until a futex_wakeup */
60	        do_block(&current_running->list, &node->block_queue);
61	        scheduler();
62	    }
63	
64	    enable_preempt();
65	}
