67	void futex_wakeup(volatile uint64_t *val_addr, int num_wakeup)
68	{
69	    disable_preempt();
70	
71	    futex_node_t *node = get_node(val_addr, 0);
72	    if (node != NULL) {
73	        for (int i = 0; i < num_wakeup; ++i) {
74	            if (list_empty(&node->block_queue)) {
75	                break;
76	            }
77	            do_unblock(node->block_queue.next);
78	        }
79	    }
80	    scheduler();
81	
82	    enable_preempt();
83	}

