44	static void init_pcb_stack(ptr_t kernel_stack, ptr_t user_stack, ptr_t entry_point, pcb_t *pcb)
45	{
46	    regs_context_t *pt_regs = (regs_context_t *)(kernel_stack - sizeof(regs_context_t));
47	    pcb->kernel_sp -= sizeof(regs_context_t);
48	
49	    /* initialization registers: ra, sp, gp, sepc, sstatus, sepc, sscratch */
50	    pt_regs->regs[1] = (reg_t)entry_point;      //ra
51	    pt_regs->regs[2] = (reg_t)user_stack;       //sp
52	    pt_regs->regs[3] = (reg_t)__global_pointer$;//gp
53	    if(pcb->type == USER_PROCESS || pcb->type == USER_THREAD){
54	        pt_regs->sstatus = (reg_t)SR_SPIE;      //SPP = 0, SPIE = 1
55	        pt_regs->sepc = (reg_t)entry_point;
56	        pt_regs->sscratch = (reg_t)pcb;         //sscratch = tp
57	    }
58	    else{
59	        pt_regs->sstatus = (reg_t)(SR_SPP | SR_SPIE);  //SPP = 1, SPIE = 1
60	        pt_regs->sepc = (reg_t)entry_point;
61	        pt_regs->sscratch = (reg_t)0;                  //sscratch = 0
62	    }
63	}
